// Coprime deck sizes give each calendar day a distinct pairing for 437 days.
const openings = [
  'Хороший вопрос уже задаёт направление.', 'Сложная тема становится ближе с каждым разобранным примером.',
  'Любопытство заслуживает места в расписании.', 'Первый черновик даёт материал для второй попытки.',
  'Одна точная мысль стоит целой страницы туманных заметок.', 'Самая интересная деталь часто прячется в ошибке.',
  'Понимание растёт, когда объясняешь своими словами.', 'Идея крепнет при встрече с реальной задачей.',
  'У разговора есть шанс изменить ход твоей работы.', 'Даже короткое наблюдение может стать гипотезой.',
  'Мастерство складывается из возвращений к практике.', 'Смелость иногда звучит как простой вопрос.',
  'Внимание — ресурс, которым ты распоряжаешься сам.', 'Прогресс легче заметить по следам своей работы.',
  'У сложной задачи всегда есть детали, которые можно изучить.', 'Новый навык начинается с непривычного движения.',
  'Собственный темп помогает пройти длинную дистанцию.', 'Открытие начинается в момент, когда замечаешь странность.',
  'Сегодняшняя попытка даст тебе новые данные.'
];
const prompts = [
  'Выбери вопрос, на который к вечеру хочешь ответить.', 'Проверь одно предположение на простом примере.',
  'Нарисуй схему того, что пока трудно объяснить.', 'Оставь себе запись, с которой завтра будет легко начать.',
  'Отведи десять минут идее, к которой постоянно возвращаешься.', 'Попробуй объяснить трудное место вслух.',
  'Запиши, что изменилось в твоём понимании за день.', 'Покажи черновик человеку, чьему взгляду доверяешь.',
  'Разбери одну ошибку до момента, где мысль свернула в сторону.', 'Сформулируй следующий шаг одним глаголом.',
  'Задай вопрос, который давно откладывал.', 'Сравни первую попытку с последней.',
  'Отложи телефон на время первого подхода.', 'Перескажи одну идею по памяти, затем сверься с источником.',
  'Придумай задачу, на которой можно испытать новую идею.', 'Выдели в расписании время для самого интересного дела.',
  'Дай одной задаче четверть часа полного внимания.', 'Найди один пример из собственной практики.',
  'Спроси коллегу, как он подошёл бы к той же задаче.', 'Отметь результат, который уже можно показать.',
  'Доведи один начатый фрагмент до ясного вывода.', 'Запиши первую версию ответа до того, как откроешь учебник.',
  'Назови одну вещь, которую теперь умеешь делать самостоятельно.'
];
export function dailyPhrase(date) {
  const day = Math.floor(Date.parse(date + 'T00:00:00Z') / 86400000);
  const index = size => ((day % size) + size) % size;
  return openings[index(openings.length)] + ' ' + prompts[index(prompts.length)];
}
